/// <summary>
/// Add Corrected invoiceId/Datee for edi credit not
/// </summary>
public void postLoad()
{
    next postLoad();

    if (this.InvoiceAmount<0)
    {
        CustVendCreditInvoicingTable custVendCreditInvoicingTable;
        SalesTable locSalesTable;
        select firstonly RecId, SalesId from locSalesTable
            where locSalesTable.SalesId==this.SalesId;
        select firstonly custVendCreditInvoicingTable
            order by RecId desc
            where custVendCreditInvoicingTable.RefRecId==locSalesTable.RecId
            && custVendCreditInvoicingTable.RefTableId==tableNum(salesTable);
        if (custVendCreditInvoicingTable)
        {
            this.AVARUMCorrectedInvoiceId=custVendCreditInvoicingTable.CustVendCorrectedInvoiceId;
            this.AVARUMCorrectedInvoiceDate=custVendCreditInvoicingTable.CustVendCorrectedInvoiceDate;
        }
    }
}
